BACKGROUNDS = {"kitchen": kitchen, "living_room": living_room, "bedroom": bedroom}


@functools.lru_cache(maxsize=8)
def background(name: str) -> Image.Image:
    if name not in BACKGROUNDS:
        raise KeyError(f"Unknown background '{name}'. Known: {sorted(BACKGROUNDS)}")
    img, p = _canvas()
    BACKGROUNDS[name](p)
    return _finish(img).convert("RGB")


