PROP_RES = 2.5


@functools.lru_cache(maxsize=None)
def _prop_sprite(name):
    bbox, fn, _, _ = PROPS[name]
    return make_sprite(bbox, fn, PROP_RES)


@functools.lru_cache(maxsize=4000)
def prop_image(name: str, k_q: int, ang_q: int):
    """Scaled + rotated prop with its grip/pivot location."""
    spr = _prop_sprite(name)
    _, _, (gx, gy), _ = PROPS[name]
    k = k_q / 100
    f = k / spr.res
    w, h = spr.img.size
    W, H = max(1, int(w * f)), max(1, int(h * f))
    img = spr.img.resize((W, H), Image.LANCZOS)
    px, py = (spr.px + gx * spr.res) * f, (spr.py + gy * spr.res) * f
    if ang_q:
        a = math.radians(ang_q)
        rot = img.rotate(-ang_q, resample=Image.BICUBIC, expand=True)
        vx, vy = px - W / 2, py - H / 2
        px = rot.size[0] / 2 + vx * math.cos(a) - vy * math.sin(a)
        py = rot.size[1] / 2 + vx * math.sin(a) + vy * math.cos(a)
        img = rot
    return img, px, py


def draw_prop(layer: Image.Image, name: str, x: float, y: float, angle: float, k: float, extra_rot: float = 0,
              held: bool = False):
    if name not in PROPS:
        raise KeyError(f"Unknown prop '{name}'. Known: {sorted(PROPS)}")
    off = PROPS[name][3]
    if held and off is None:
        ang = int(round(extra_rot)) % 360          # upright props ignore the hand angle
    else:
        ang = int(round(angle + (off or 0) + extra_rot)) % 360
    img, px, py = prop_image(name, max(5, int(round(k * 100))), ang)
    layer.alpha_composite(img, (int(round(x - px)), int(round(y - py))))


# ----------------------------------------------------------------------------
# Effects
# ----------------------------------------------------------------------------
def fx_overlay(frame: Image.Image, fx: dict, t: float, cam):
    """Apply one effect to the frame. t is seconds since the effect started."""
    kind = fx["type"]
    W, H = frame.size
    dur = fx.get("dur", 0.4)
    if kind == "flash":
        a = max(0.0, 1 - t / dur)
        if a > 0:
            frame.paste(Image.blend(frame, Image.new("RGB", frame.size, fx.get("color", "#FFFFFF")), a * 0.85))
    elif kind == "darkness":
        dark = Image.new("RGB", frame.size, (20, 24, 60))
        frame.paste(Image.blend(frame, dark, fx.get("amount", 0.72)))
    elif kind == "vignette":
        _vignette(frame, fx.get("amount", 0.5))
    elif kind == "speedlines":
        d = ImageDraw.Draw(frame)
        rnd = random.Random(int(t * 30))
        cx, cy = cam.to_screen(*fx.get("pos", (540, 960)))
        for _ in range(46):
            a = rnd.random() * 2 * math.pi
            r0 = 380 + rnd.random() * 200
            r1 = r0 + 300 + rnd.random() * 500
            d.line([(cx + math.cos(a) * r0, cy + math.sin(a) * r0), (cx + math.cos(a) * r1, cy + math.sin(a) * r1)],
                   fill=(255, 255, 255), width=4 + rnd.randint(0, 6))
    elif kind in ("text", "burst"):
        pop = min(1.0, t / 0.12)
        scale = 0.6 + 0.4 * pop + 0.04 * math.sin(t * 20)
        x, y = cam.to_screen(*fx.get("pos", (540, 600))) if fx.get("world", True) else fx.get("pos", (540, 600))
        size = int(fx.get("size", 120) * scale)
        f = font(max(10, size))
        txt = fx["text"]
        d = ImageDraw.Draw(frame)
        if kind == "burst":
            pts = []
            n = 14
            tw = f.getlength(txt)
            rx = max(size * 2.0, tw * 0.5 / 0.72 + size * 0.45)   # inner points clear the text
            ry = max(size * 1.36, size * 0.8 / 0.72 + size * 0.35)
            for i in range(2 * n):
                k = 1.0 if i % 2 == 0 else 0.72
                a = math.pi * i / n + t * 0.8
                pts.append((x + math.cos(a) * rx * k, y + math.sin(a) * ry * k))
            d.polygon(pts, fill=rgba(fx.get("bg", "#FFD23F")), outline=(30, 20, 16), width=8)
        d.text((x, y), txt, font=f, fill=rgba(fx.get("color", "#FFFFFF")), anchor="mm",
               stroke_width=max(4, size // 12), stroke_fill=(30, 20, 16))
    elif kind == "sweat":
        x, y = cam.to_screen(*fx["pos"])
        d = ImageDraw.Draw(frame)
        for i in range(3):
            ph = (t * 1.5 + i / 3) % 1
            sx, sy = x + (i - 1) * 50 * cam.zoom, y + ph * 90 * cam.zoom
            r = 14 * cam.zoom
            d.ellipse([sx - r, sy - r, sx + r, sy + r * 1.6], fill=(150, 210, 255), outline=(30, 20, 16), width=4)
    elif kind == "marks":   # !! or ?? floating over a head
        x, y = cam.to_screen(*fx["pos"])
        bob = math.sin(t * 9) * 8
        d = ImageDraw.Draw(frame)
        d.text((x, y + bob), fx.get("text", "!!"), font=font(int(110 * cam.zoom ** 0.5)), fill=(255, 210, 63),
               anchor="mm", stroke_width=8, stroke_fill=(30, 20, 16))
    elif kind == "dust":   # chase dust cloud
        x, y = cam.to_screen(*fx["pos"])
        d = ImageDraw.Draw(frame)
        rnd = random.Random(7)
        for i in range(14):
            a = rnd.random() * 6.28
            r = (40 + rnd.random() * 120) * (0.6 + t)
            rr = 40 + 30 * math.sin(t * 6 + i)
            cx, cy = x + math.cos(a) * r, y + math.sin(a) * r * 0.5
            d.ellipse([cx - rr, cy - rr, cx + rr, cy + rr], fill=(235, 228, 214), outline=(30, 20, 16), width=5)
    elif kind == "smoke":   # grey puffs rising from a point
        x, y = cam.to_screen(*fx["pos"])
        over = Image.new("RGBA", frame.size, (0, 0, 0, 0))
        d = ImageDraw.Draw(over)
        for i in range(12):
            ph = (t * 0.55 + i / 12) % 1
            rnd = random.Random(i)
            r = (30 + ph * 110) * cam.zoom * fx.get("size", 1.0)
            cx = x + (rnd.random() - 0.5) * 80 * cam.zoom + math.sin(ph * 5 + i) * 40 * cam.zoom
            cy = y - ph * 520 * cam.zoom * fx.get("size", 1.0)
            a = int(200 * (1 - ph))
            d.ellipse([cx - r, cy - r, cx + r, cy + r], fill=(110, 110, 118, a))
        frame.paste(Image.alpha_composite(frame.convert("RGBA"), over).convert("RGB"))
    elif kind == "blink":   # small flashing light (router LEDs, alarms)
        if int(t * fx.get("rate", 4) * 2) % 2 == 0:
            x, y = cam.to_screen(*fx["pos"])
            r = fx.get("radius", 10) * cam.zoom
            d = ImageDraw.Draw(frame)
            d.ellipse([x - r, y - r, x + r, y + r], fill=rgba(fx.get("color", "#FF3B30")))
    elif kind == "spotlight":   # dark room lit by one soft pool of light (fridge, phone, lamp)
        x, y = cam.to_screen(*fx["pos"])
        rx, ry = fx.get("radius", (260, 420))
        rx, ry = rx * cam.zoom, ry * cam.zoom
        W2, H2 = W // 4, H // 4
        m = Image.new("L", (W2, H2), 0)
        ImageDraw.Draw(m).ellipse([(x - rx) / 4, (y - ry) / 4, (x + rx) / 4, (y + ry) / 4], fill=255)
        m = m.filter(ImageFilter.GaussianBlur(max(4, int(rx / 12)))).resize((W, H), Image.BILINEAR)
        dark = Image.blend(frame, Image.new("RGB", frame.size, (12, 14, 40)), fx.get("amount", 0.8))
        if fx.get("tint"):
            lit = Image.blend(frame, Image.new("RGB", frame.size, fx["tint"]), 0.12)
        else:
            lit = frame
        frame.paste(Image.composite(lit, dark, m))
    elif kind == "camfeed":   # grainy security-camera look
        g = frame.convert("L").convert("RGB")
        g = Image.blend(g, Image.new("RGB", frame.size, (40, 70, 40)), 0.18)
        d = ImageDraw.Draw(g)
        for yy in range(0, H, 6):
            d.line([(0, yy), (W, yy)], fill=(0, 0, 0), width=1)
        if int(t * 2) % 2 == 0:
            d.ellipse([60, 120, 100, 160], fill=(230, 40, 40))
        d.text((120, 140), "REC  CAM 2  KITCHEN", font=font(44), fill=(235, 235, 235), anchor="lm")
        d.text((W - 60, 140), fx.get("stamp", "03:12:44"), font=font(40), fill=(235, 235, 235), anchor="rm")
        frame.paste(g)
    else:
        raise KeyError(f"Unknown fx '{kind}'")


FX_TYPES = ["flash", "darkness", "vignette", "speedlines", "text", "burst", "sweat", "marks", "dust", "shake", "smoke", "blink", "spotlight", "camfeed"]


@functools.lru_cache(maxsize=4)
def _vignette_mask(size, amount):
    W, H = size
    m = Image.new("L", (W // 8, H // 8), 0)
    d = ImageDraw.Draw(m)
    d.ellipse([-W // 40, -H // 60, W // 8 + W // 40, H // 8 + H // 60], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(18)).resize(size, Image.BILINEAR)
    return m.point(lambda v: int(255 - (255 - v) * amount))


def _vignette(frame, amount):
    black = Image.new("RGB", frame.size, (10, 8, 20))
    frame.paste(Image.composite(frame, black, _vignette_mask(frame.size, amount)))



